mapper.select:
SELECT m.* FROM sys_menu m
INNER JOIN sys_role_menu rm ON m.id = rm.menu_id
WHERE rm.role_id = #{roleId}

mapper.update:
UPDATE sys_menu
menu_name = #{menuName}, path = #{path}, component = #{component}, perms = #{perms}, icon = #{icon}, sort = #{sort}, visible = #{visible},
WHERE id = #{id}
